import{_ as u,a0 as a,w as n,s as l,ao as s,I as r,x as i,a1 as p,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const H=JSON.parse('{"title":"GitHub 對軟件開發業造成的衝擊 | LCTT x X-CMD","titleTemplate":false,"description":"GitHub 對軟件開發業造成的衝擊 | LCTT (201707) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"GitHub 對軟件開發業造成的衝擊 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"GitHub 對軟件開發業造成的衝擊 | LCTT (201707) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201707/20170309 The impact GitHub is having on your software career","title":"GitHub 對軟件開發業造成的衝擊","tag":"201707","desc":""},"relativePath":"201707/20170309 The impact GitHub is having on your software career.md","filePath":"[post].md"}'),T={name:"201707/20170309 The impact GitHub is having on your software career.md"};function b(m,t,f,d,g,h){const e=a("Link");return n(),l("div",null,[t[16]||(t[16]=s('<h1 id="github-對軟件開發業造成的衝擊" tabindex="-1">GitHub 對軟件開發業造成的衝擊 <a class="header-anchor" href="#github-對軟件開發業造成的衝擊" aria-label="Permalink to “GitHub 對軟件開發業造成的衝擊”">​</a></h1><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/images/life/github-universe.jpg?itok=HCU81VX8" alt="The impact GitHub is having on your software career" title="The impact GitHub is having on your software career"></p><p>在未來的 12 到 24 個月內（也就是説，在 2018 年，或者是 2019 年），人們僱傭軟件開發者的方式將會發生徹底的改變。</p><p>2004 至 2014 期間，我曾經就職於紅帽，這是世界上最大的開源軟件公司。還記得 2004 年七月的一天，我第一次來到這家公司，我的老闆 Marty Messer 就跟我説，“所有你在這裏所做的工作都會被開源，在未來，你將不需要任何的簡歷，因為所有的人都可以 Google 到你。”</p><p>供職於紅帽的一個獨特的好處是，在這種開源的工作期間，我們有機會建立自己的個人品牌和樹立自己的聲譽。我們可以通過郵件列表和 bug 追蹤器與其它的軟件工程師進行溝通，而且提交到 mercurial、subversion 和 CVS 倉庫的源代碼都會被開源，並且可以通過 google 找到。</p><p>（寫本文時）馬上就到 2017 年了，我們將生活在一個處處充滿開源的世界。</p><p>以下兩點會讓你對這個新時代有一個真正意義上的瞭解：</p><ol><li>微軟在過去的一段很長的時間裏都在堅持閉源，甚至是排斥開源。但是現在也從心底裏開始擁抱開源了。它們成立了 .NET 基金會（紅帽也是其中的一個成員），並且也加入了 Linux 基金會。 .NET 項目現在是以一個開源項目的形式在開發着。</li><li>Github 已經成為了一個獨特的社交網絡，並將問題追蹤器和分佈式源碼版本控制融入其中。</li></ol><p>對於那些從閉源走過來的軟件開發者來説，他們可能還不知道發生了什麼。對於他們來説 ，開源就意味着“將業餘時間的所有工作成果都免費開放”。</p><p>對於我們這些在過去十年創造了一家十億美元的開源軟件公司的人來説，參與開源以後就沒有什麼空閒的時間可言了。當然，為開源事業獻身的好處也是很明顯的，所得到的名譽是你自己的，並不隸屬於某個公司。GitHub 是一個社交網絡，在這個地方，你可以創建你的提交、你可以在你所專長的領域為一些全球性的組織做出貢獻，你臨時做的一些工作並不附屬於所任職的公司。</p><p>聰明的人會利用這種工作環境。他們會貢獻他們的補丁、工單（issue）、評論給他們平時在工作中使用的語言和框架，比如 TypeScript、 .NET 和 Redux 。</p><p>他們也擁抱開源，並會盡可能多的開源他們的創新成果。甚至會提交他們的貢獻給私有倉庫。</p><p>GitHub 對平等居功至偉。比如説，你也許很難在澳大利亞得到一份來自印度的工作，但是，在 GitHub 上，卻沒有什麼可以阻止你在印度跟澳大利亞的工作夥伴一起工作。</p><p>在過去十年裏，想從紅帽獲得一個工作機會的方式很簡單。你只需要在一些某些小的方面，與紅帽的軟件工程師在開源的項目上協作，然後當他們覺得你在某些方面做出了很多有價值的貢獻，而且成為一個很好的工作夥伴時，那麼你就可以申請一個紅帽的工作機會了，或許他們會邀請你。</p><p>現在，在不同的技術領域，開源給了我們所有人同樣的機會，隨着開源在世界的各處都流行開來，這樣的事情將會在不同的地方盛行開來。</p>',15)),r("p",null,[t[1]||(t[1]=i("在",-1)),p(e,{href:"http://www.theregister.co.uk/2017/02/15/think_different_shut_up_and_work_harder_says_linus_torvalds/"},{default:o(()=>[...t[0]||(t[0]=[i("最近一個訪談",-1)])]),_:1}),t[2]||(t[2]=i("中，Linux 和 git 的發明者 Linux Torvalds（在 GitHub 上有 49K 粉絲，0 關注），這麼説，",-1))]),t[17]||(t[17]=s("<blockquote><p>“你提交了很多小補丁，而在某個時候項目的維護者開始信任你，在那一刻，你跟一般人不同的是，你不僅僅是提交了一些補丁，而是真正成為了這個組織里被信任的一部分。”</p></blockquote><p>實際上你的名聲存在於那個你被信任的網絡。我們都知道，當你離開一家公司以後，你的人脈和名聲可能會削弱，有的甚至會丟失。就好像，你在一個小村莊裏生活了很長的一段時間，這裏所有的人都會知道你。然而，當你離開這個村莊，來到一個新的地方，這個地方可能沒人聽説過你，更糟糕的是，沒有人認識任何知道你的人。</p><p>你已經失去了一度和二度連接關係，甚至有可能會失去這三度連接關係（LCTT 譯註：指六度連接理論）。除非你通過在會議或其他大型活動中演講來建立自己的品牌，否則你通過在公司內部提交代碼建立起來的信任早晚都會過去的，但是，如果你在 GitHub 上完成你的工作，這些東西依然全部都在，對這個信任網絡的連接仍然可見。</p><p>首先會發生的事情就是，一些弱勢羣體可能會利用這個。包括像學生、新畢業生、移民者--他們可能會利用這個“去往”澳大利亞。</p><p>這將會改變目前的現狀。以前的一些開發人員可能會有過人際網絡突然中斷的情況，開源的一個原則是精英——最好的創意、最多的提交、最多的測試，和最快的落實執行，等等。</p><p>它並不完美，當然也沒有什麼事情是完美的，不能和夥伴一起工作，在人們對你的印象方面也會大打折扣。紅帽公司會開除那些不能和團隊和諧相處的人，而在 GitHub 工作的這些員工，他們主要是和其它的貢獻者之間的交流。</p><p>GitHub 不僅僅是一個代碼倉庫或是一個原始提交成員的列表，因為有些人總是用稻草人論點描述它。它是一個社交網絡。我會這樣説：</p><blockquote><p>GitHub 有多少代碼並不重要，重要的是有多少關於你代碼的討論。</p></blockquote><p>GitHub 可以説是伴你而走的名聲，並且在以後的 12 到 24 個月中，很多開發者使用它，而另外的一些依然並不使用，這將會形成一個很明顯的差異。就像有電子郵件和沒有電子郵件的區別（現在每個人都有電子郵件了），或者是有移動電話和沒有移動電話的區別（現在每個人都有移動電話了），最終，絕大多數的人都會為開源工作，這將會是與別人的競爭中的一個差異化的優勢。</p><p>但是現在，開發者的職業生涯已經被 GitHub 打亂了。</p><p>（題圖： GitHub）</p><hr><p>作者簡介：</p><p>Josh Wulf - 我是 Just Digital People 的傳奇招聘者，前紅帽員工，CoderDojo 導師， Magikcraft.io 創始人之一，The JDP Internship 出品人——這是世界第一的軟件開發真人秀，世界上最好的科技播客主持人，也是一位父親。一直致力於昆士蘭州的“硅經濟”。</p><hr>",15)),r("p",null,[t[4]||(t[4]=i("via: ",-1)),p(e,{href:"https://medium.com/@sitapati/the-impact-github-is-having-on-your-software-career-right-now-6ce536ec0b50"},{default:o(()=>[...t[3]||(t[3]=[i("https://medium.com/@sitapati/the-impact-github-is-having-on-your-software-career-right-now-6ce536ec0b50",-1)])]),_:1})]),r("p",null,[t[8]||(t[8]=i("作者：",-1)),p(e,{href:"https://opensource.com/users/sitapati"},{default:o(()=>[...t[5]||(t[5]=[i("Josh Wulf",-1)])]),_:1}),t[9]||(t[9]=i(" 譯者：",-1)),p(e,{href:"https://github.com/SysTick"},{default:o(()=>[...t[6]||(t[6]=[i("SysTick",-1)])]),_:1}),t[10]||(t[10]=i(" 校對：",-1)),p(e,{href:"https://github.com/wxy"},{default:o(()=>[...t[7]||(t[7]=[i("wxy",-1)])]),_:1})]),r("p",null,[t[13]||(t[13]=i("本文由 ",-1)),p(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[11]||(t[11]=[i("LCTT",-1)])]),_:1}),t[14]||(t[14]=i(" 原創編譯，",-1)),p(e,{href:"https://linux.cn/"},{default:o(()=>[...t[12]||(t[12]=[i("Linux中國",-1)])]),_:1}),t[15]||(t[15]=i(" 榮譽推出",-1))])])}const C=u(T,[["render",b]]);export{H as __pageData,C as default};
